function heap_push(queue, item)
{
    queue.append(item)
    let index = queue.len() - 1
    while (index > 0) {
        let parent = (index - 1) / 2
        let above = queue[parent]
        if (above[0] < item[0] or (above[0] == item[0] and above[1] <= item[1])) { break }
        queue[index] = above
        index = parent
    }
    queue[index] = item
}

function heap_pop(queue)
{
    let root = queue[0]
    let last = queue[queue.len() - 1]
    delete(queue, queue.len() - 1)
    let size = queue.len()
    if (size > 0) {
        let index = 0
        while (index * 2 + 1 < size) {
            let child = index * 2 + 1
            if (child + 1 < size) {
                let a = queue[child]
                let b = queue[child + 1]
                if (b[0] < a[0] or (b[0] == a[0] and b[1] < a[1])) { child = child + 1 }
            }
            let below = queue[child]
            if (last[0] < below[0] or (last[0] == below[0] and last[1] <= below[1])) { break }
            queue[index] = below
            index = child
        }
        queue[index] = last
    }
    return copy(root)
}

